INSERT INTO customer SELECT * REPLACE (c_custkey + 3000000000 AS c_custkey) FROM customer WHERE c_custkey IN (SELECT o_custkey FROM orders WHERE o_orderkey < 2147483648 AND o_orderkey % 8 = 0) AND NOT EXISTS (SELECT 1 FROM customer AS c WHERE c.c_custkey = customer.c_custkey + 3000000000);
INSERT INTO orders SELECT * REPLACE (o_orderkey + 3000000000 AS o_orderkey, o_custkey + 3000000000 AS o_custkey) FROM orders WHERE o_orderkey < 2147483648 AND o_orderkey % 8 = 0 AND NOT EXISTS (SELECT 1 FROM orders AS c WHERE c.o_orderkey = orders.o_orderkey + 3000000000);
